import type { FolderNode, TreeNode } from '../state/schema';
import { baseName, joinPath, parentPath, type RelPath } from './ports';

/**
 * File naming rules of the markdown convention (spec 004 FR-004, research R5):
 * safe stems for common desktop file systems, case-insensitive sibling
 * uniqueness with " (N)" suffixes, and stability across runs (an item keeps its
 * previous path while that path still matches its name).
 */

export const ENTRY_EXT = 'md';
export const FOLDER_RECORD_NAME = '.wiw-folder.yaml';
export const IMAGE_EXTS: readonly string[] = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'avif', 'bmp', 'jfif'];

const MAX_STEM = 120;
const RESERVED = /^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i;
const SUFFIX = / \((\d+)\)$/;

export function sanitizeStem(name: string): string {
    let stem = name
        .normalize('NFC')
        // Control characters are part of the rule set (research R5).
        // eslint-disable-next-line no-control-regex
        .replace(/[<>:"/\\|?*�-]/g, '_')
        .trim()
        .replace(/[. ]+$/, '');
    stem = stem.replace(/^\.+/, (dots) => '_'.repeat(dots.length));
    if (RESERVED.test(stem)) {
        stem = `${stem}_`;
    }
    const chars = Array.from(stem);
    if (chars.length > MAX_STEM) {
        stem = chars.slice(0, MAX_STEM).join('').replace(/[. ]+$/, '');
    }
    if (stem === '') {
        return 'Untitled';
    }
    return stem;
}

export function nameKey(name: string): string {
    return name.normalize('NFC').toLocaleLowerCase();
}

export function compareDiskNames(
    a: { name: string; isDir: boolean },
    b: { name: string; isDir: boolean }
): number {
    if (a.isDir !== b.isDir) {
        return a.isDir ? -1 : 1;
    }
    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base', numeric: true });
}

const MIME_EXT: Record<string, string> = {
    'image/png': 'png',
    'image/jpeg': 'jpg',
    'image/jpg': 'jpg',
    'image/gif': 'gif',
    'image/webp': 'webp',
    'image/svg+xml': 'svg',
    'image/avif': 'avif',
    'image/bmp': 'bmp',
};

export const EXT_MIME: Record<string, string> = {
    png: 'image/png',
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    jfif: 'image/jpeg',
    gif: 'image/gif',
    webp: 'image/webp',
    svg: 'image/svg+xml',
    avif: 'image/avif',
    bmp: 'image/bmp',
};

export function imageExtFromSrc(src: string): string | null {
    if (src.startsWith('data:')) {
        const mime = src.slice(5).split(/[;,]/)[0]?.toLowerCase() ?? '';
        return MIME_EXT[mime] ?? null;
    }
    const clean = src.split(/[?#]/)[0] ?? '';
    const ext = clean.includes('.') ? clean.slice(clean.lastIndexOf('.') + 1).toLowerCase() : '';
    return IMAGE_EXTS.includes(ext) ? ext : null;
}

/**
 * Deterministic rule: an image has a file on disk iff its bytes are reachable
 * without a cross-origin request — a data URI or a same-origin app path.
 * External URLs are URL-only images recorded in the folder record.
 */
export function imageHasFile(src: string): boolean {
    if (src === '') {
        return false;
    }
    if (src.startsWith('data:')) {
        return imageExtFromSrc(src) !== null;
    }
    if (/^[a-z][a-z0-9+.-]*:/i.test(src) || src.startsWith('//')) {
        return false;
    }
    return imageExtFromSrc(src) !== null;
}

export function isImageFileName(name: string): boolean {
    const ext = name.includes('.') ? name.slice(name.lastIndexOf('.') + 1).toLowerCase() : '';
    return IMAGE_EXTS.includes(ext);
}

export function splitName(name: string): { stem: string; ext: string } {
    const at = name.lastIndexOf('.');
    return at <= 0 ? { stem: name, ext: '' } : { stem: name.slice(0, at), ext: name.slice(at + 1) };
}

interface Desired {
    id: string;
    /** The item name as is (a previous file named exactly like it is kept). */
    rawName: string;
    stem: string;
    ext: string;
    isDir: boolean;
}

function desiredOf(node: TreeNode): Desired | null {
    const stem = sanitizeStem(node.name);
    if (node.kind === 'folder') {
        return { id: node.id, rawName: node.name, stem, ext: '', isDir: true };
    }
    if (node.kind === 'entry') {
        return { id: node.id, rawName: node.name, stem, ext: ENTRY_EXT, isDir: false };
    }
    if (!imageHasFile(node.src)) {
        return null;
    }
    return { id: node.id, rawName: node.name, stem, ext: imageExtFromSrc(node.src) ?? 'png', isDir: false };
}

function fileName(stem: string, ext: string): string {
    return ext === '' ? stem : `${stem}.${ext}`;
}

/**
 * Assigns a relative path to every node of `scope` (the scope folder itself maps to
 * `baseDir`). URL-only images get no path. `previous` holds the paths of an earlier
 * run (baseline) and is honored while still consistent with the item's name.
 */
export function assignPaths(
    scope: FolderNode,
    previous: ReadonlyMap<string, RelPath>,
    baseDir: RelPath
): Map<string, RelPath> {
    const paths = new Map<string, RelPath>();
    paths.set(scope.id, baseDir);
    const visit = (folder: FolderNode, dir: RelPath): void => {
        const taken = new Set<string>([nameKey(FOLDER_RECORD_NAME)]);
        const wanted = folder.children
            .map((child) => desiredOf(child))
            .filter((item): item is Desired => item !== null);
        const assigned = new Map<string, string>();
        // Pass 1: keep previous names that still match the desired stem.
        for (const item of wanted) {
            const prev = previous.get(item.id);
            if (prev === undefined || parentPath(prev) !== dir) {
                continue;
            }
            const prevName = baseName(prev);
            const { stem: prevStem, ext: prevExt } = item.isDir ? { stem: prevName, ext: '' } : splitName(prevName);
            const unsuffixed = prevStem.replace(SUFFIX, '');
            // A user-made file named exactly like the item (even with characters the
            // sanitizer would replace) is kept: linking must not rename user files.
            const sameName =
                nameKey(prevStem) === nameKey(item.stem) ||
                nameKey(unsuffixed) === nameKey(item.stem) ||
                prevStem === item.rawName;
            if (
                (item.isDir || nameKey(prevExt) === nameKey(item.ext)) &&
                sameName &&
                !taken.has(nameKey(prevName))
            ) {
                taken.add(nameKey(prevName));
                assigned.set(item.id, prevName);
            }
        }
        // Pass 2: fresh names with collision suffixes.
        for (const item of wanted) {
            if (assigned.has(item.id)) {
                continue;
            }
            let candidate = fileName(item.stem, item.ext);
            for (let n = 2; taken.has(nameKey(candidate)); n++) {
                candidate = fileName(`${item.stem} (${n})`, item.ext);
            }
            taken.add(nameKey(candidate));
            assigned.set(item.id, candidate);
        }
        for (const child of folder.children) {
            const name = assigned.get(child.id);
            if (name === undefined) {
                continue;
            }
            const path = joinPath(dir, name);
            paths.set(child.id, path);
            if (child.kind === 'folder') {
                visit(child, path);
            }
        }
    };
    visit(scope, baseDir);
    return paths;
}
